ALTER TABLE "app"."lead_turn_runtime" ADD CONSTRAINT "lead_turn_runtime_child_allowance_valid" CHECK (("app"."lead_turn_runtime"."child_allowance_state" is null and "app"."lead_turn_runtime"."child_allowance_plan_digest" is null and "app"."lead_turn_runtime"."child_allowance_maximum_microunits" is null and "app"."lead_turn_runtime"."child_allowance_maximum_tokens" is null) or ("app"."lead_turn_runtime"."child_allowance_state" = 'not_stated' and "app"."lead_turn_runtime"."child_allowance_plan_digest" ~ '^sha256:[a-f0-9]{64}$' and "app"."lead_turn_runtime"."child_allowance_maximum_microunits" is null and "app"."lead_turn_runtime"."child_allowance_maximum_tokens" is null) or ("app"."lead_turn_runtime"."child_allowance_state" = 'stated' and "app"."lead_turn_runtime"."child_allowance_plan_digest" ~ '^sha256:[a-f0-9]{64}$' and "app"."lead_turn_runtime"."child_allowance_maximum_microunits" between 0 and 9007199254740991 and "app"."lead_turn_runtime"."child_allowance_maximum_tokens" between 0 and 9007199254740991));